#include <bits/stdc++.h>
using namespace std;

long long ch[122][122];
int cntA[122], cntB[122];
long long best = LLONG_MAX;
string str;
unordered_map<long long, long long> cache;
int R, C;

void initializePascal() {
    int maxVal = 2 * (R + C);
    for (int i = 0; i <= maxVal; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == 0 || j == i) ch[i][j] = 1;
            else ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j];
        }
    }
}

long long computeInitialDiffs() {
    long long x = 0, y = 0;
    int v1 = R + C, v2 = R + C;
    while (v1 >= R && v2 >= R) {
        if (x > y) {
            long long cur = ch[v1][R] - ch[v1 - 1][R];
            long long other = ch[v2][R];
            y += cur * other;
            v1--;
        } else {
            long long cur = ch[v2][R] - ch[v2 - 1][R];
            long long other = ch[v1][R];
            x += cur * other;
            v2--;
        }
    }
    return abs(x - y);
}

void processStringCounts() {
    cntA[0] = 0;
    cntB[0] = 0;
    int len = (int)str.size();
    for (int i = 0; i < len; i++) {
        cntA[i + 1] = cntA[i] + (str[i] == 'A' ? 1 : 0);
        cntB[i + 1] = cntB[i] + (str[i] == 'B' ? 1 : 0);
    }
}

long long solve(long long x, long long y, int v1, int v2) {
    long long diff = abs(x - y);
    if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
    long long key = x * 1000000LL + v1 * 1000LL + v2;
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;
    if (v1 < R || v2 < R) {
        int sum = v1 + v2;
        if (v1 >= cntA[sum] && v2 >= cntB[sum]) {
            v1 -= cntA[sum];
            v2 -= cntB[sum];
            return ch[v1 + v2][v1];
        }
        return 0;
    }
    long long ans = 0;
    char c = str[v1 + v2 - 1];
    if (c != 'B') {
        long long cur = ch[v1][R] - ch[v1 - 1][R];
        long long other = ch[v2][R];
        ans += solve(x, y + cur * other, v1 - 1, v2);
    }
    if (c != 'A') {
        long long cur = ch[v2][R] - ch[v2 - 1][R];
        long long other = ch[v1][R];
        ans += solve(x + cur * other, y, v1, v2 - 1);
    }
    cache[key] = ans;
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> R >> C;
    initializePascal();
    long long initialDiff = computeInitialDiffs();
    str.clear();
    str.resize(2 * (R + C));
    for (int i = 0; i < 2 * (R + C); i++) {
        cin >> str[i];
    }
    processStringCounts();
    long long answer = solve(0, 0, R + C, R + C);
    cout << answer << "\n";
    return 0;
}

